window.REPORT_PRELOAD_CACHE["JD.html"] = {"version":"9a2737a0b03ae7204828d8287d134ea845be7dbcac07912deb71ef57df817885","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>京东集团 JD.com (NASDAQ: JD / HKEX: 9618) 深度研究报告：从供应链基础设施霸主到零售高地与盈利修复复利引擎</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Chart.js -->\n    <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n    <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n    <script>\n    tailwind.config = {\n        darkMode: 'class',\n        theme: {\n            extend: {\n                fontFamily: {\n                    sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n                    mono: ['JetBrains Mono', 'monospace'],\n                },\n                colors: {\n                    navy: {\n                        950: '#070B14',\n                        900: '#0F172A',\n                        800: '#1E293B',\n                        700: '#334155',\n                    },\n                    jdred: {\n                        400: '#FF6B6B',\n                        500: '#E1251B',\n                        600: '#C8161D',\n                    },\n                    accent: {\n                        500: '#3B82F6',\n                        600: '#2563EB',\n                    },\n                    teal: {\n                        500: '#06B6D4',\n                        600: '#0891B2',\n                    }\n                }\n            }\n        }\n    }\n    </script>\n\n    <style>\n    ::-webkit-scrollbar {\n        width: 6px;\n        height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n        background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n        background: #94A3B8;\n        border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n        background: #475569;\n    }\n\n    @media print {\n        #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n            display: none !important;\n        }\n        main {\n            margin-left: 0 !important;\n            padding: 0 !important;\n        }\n        section {\n            break-inside: avoid;\n        }\n    }\n\n    .report-card {\n        transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n        transform: translateY(-2px);\n    }\n\n    .nav-link.active {\n        background: linear-gradient(90deg, rgba(225, 37, 27, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n        border-left: 3px solid #E1251B;\n        color: #FFFFFF;\n        font-weight: 600;\n    }\n    </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-jdred-500 selection:text-white transition-colors duration-200\">\n\n    <!-- 顶部全局阅读进度条 -->\n    <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n        <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-jdred-500 via-amber-400 to-teal-500 w-0 transition-all duration-150\"></div>\n    </div>\n\n    <!-- 移动端顶部导航栏 -->\n    <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n        <div class=\"flex items-center space-x-2.5\">\n            <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-jdred-500 to-jdred-600 flex items-center justify-center font-extrabold text-white shadow\">\n                JD\n            </div>\n            <div>\n                <div class=\"text-[11px] text-jdred-400 font-semibold tracking-wider uppercase\">NASDAQ: JD / HKEX: 9618 · Equity Research</div>\n                <div class=\"text-sm font-bold leading-tight\">京东集团 JD.com 深度研究报告</div>\n            </div>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n            <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n                <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n            </button>\n            <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n                <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n            </button>\n        </div>\n    </header>\n\n    <!-- 移动端折叠抽屉菜单 -->\n    <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n        <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n        <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n            <div>\n                <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n                    <span class=\"font-bold text-white text-base\">JD 研报目录导航</span>\n                    <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n                        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n                    </button>\n                </div>\n                <ul class=\"mt-4 space-y-1.5 text-sm\">\n                    <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n                    <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n                    <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n                    <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n                    <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n                    <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n                    <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n                </ul>\n            </div>\n            <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n                <p>全球电商与供应链基础设施研究组</p>\n                <p class=\"mt-1\">数据基准：2026年11月 (2026 财年)</p>\n            </div>\n        </nav>\n    </div>\n\n    <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n    <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n        <div>\n            <!-- 机构品牌头 -->\n            <div class=\"p-5 border-b border-slate-800/80\">\n                <div class=\"flex items-center space-x-3\">\n                    <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-jdred-500 to-jdred-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-jdred-500/25\">\n                        JD\n                    </div>\n                    <div>\n                        <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-jdred-400 bg-jdred-500/15 px-2 py-0.5 rounded\">NASDAQ: JD / HK: 9618</span>\n                        <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">京东集团深度研报</h2>\n                    </div>\n                </div>\n                <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n                    自营供应链基础设施霸主 · 零售高地与盈利现金双改善复利引擎\n                </p>\n            </div>\n\n            <!-- 股票实时快照徽章 -->\n            <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">2026 上半年营收</span>\n                    <span class=\"font-mono font-bold text-white\">¥662.1B <span class=\"text-jdred-400\">(+0.7%)</span></span>\n                </div>\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">Q3 预期营收共识</span>\n                    <span class=\"font-mono font-bold text-teal-400\">~$46.0B (~¥309B)</span>\n                </div>\n                <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n                    <span class=\"text-slate-400\">核心盈利拐点</span>\n                    <span class=\"font-mono font-bold text-jdred-400\">Q2 经营利润扭亏为盈 ¥4.5B</span>\n                </div>\n            </div>\n\n            <!-- 六个核心章节目录导航 -->\n            <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n                <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n                <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n                    <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-jdred-400 mr-2\">00</span>执行摘要与核心指标</span>\n                    </a>\n                    <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n                    </a>\n                    <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n                    </a>\n                    <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n                    </a>\n                    <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n                    </a>\n                    <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n                    </a>\n                    <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n                    </a>\n                </nav>\n            </div>\n        </div>\n\n        <!-- 侧边栏底部工具栏 -->\n        <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n            <div class=\"flex items-center justify-between\">\n                <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n                <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n                    <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n                    <svg class=\"w-3.5 h-3.5 text-jdred-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                    <span class=\"dark:hidden\">深色护眼模式</span>\n                    <span class=\"hidden dark:inline\">机构亮色模式</span>\n                </button>\n            </div>\n            <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-jdred-500 hover:bg-jdred-600 text-white text-xs font-extrabold transition shadow-sm\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n                <span>打印 / 导出 PDF 研报</span>\n            </button>\n        </div>\n    </aside>\n\n    <!-- 主内容区 -->\n    <main class=\"lg:ml-[280px] min-h-screen\">\n        <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n            <!-- =========================================================\n            00. Hero 研报封面区与执行摘要\n            ========================================================= -->\n            <section id=\"sec-exec\" class=\"scroll-mt-20\">\n                <!-- 顶部研报元数据标签栏 -->\n                <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n                    <div class=\"flex flex-wrap items-center gap-2\">\n                        <span class=\"px-2.5 py-1 rounded-md bg-jdred-500/15 text-jdred-600 dark:text-jdred-400 font-bold border border-jdred-500/30\">评级：强烈买入 / 核心价值复苏标的</span>\n                        <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026 利润拐点与供应链出海深化期</span>\n                    </div>\n                    <div class=\"flex items-center space-x-3 font-mono\">\n                        <span>覆盖时间：2026年11月</span>\n                        <span>NASDAQ: JD / HK: 9618</span>\n                    </div>\n                </div>\n\n                <!-- Hero 标题卡片 -->\n                <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n                    <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#E1251B 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n                    <div class=\"relative z-10\">\n                        <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-jdred-500/20 border border-jdred-500/40 text-jdred-400 text-xs font-semibold mb-4\">\n                            <span class=\"w-2 h-2 rounded-full bg-jdred-400 animate-pulse\"></span>\n                            <span>CORE THESIS · 自营供应链极致效率 × Q2 经营利润强势扭亏为盈（¥4.5B）与现金流双改善</span>\n                        </div>\n                        <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n                            京东集团 JD.com (NASDAQ: JD / HKEX: 9618) 深度研究报告：从自营供应链基础设施霸主到零售高地与盈利修复复利引擎\n                        </h1>\n                        <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n                            京东集团在历经激烈的价格竞争与新业务（如外卖及即时零售）战略投入期后，在 2026 年迎来了<strong class=\"text-white\">盈利修复拐点与现金流质量大幅改善</strong>的双重验证。2026 上半年总营收达到 <strong class=\"text-jdred-400\">¥662.1B (+0.7%)</strong>，其中 Q2 经营利润强势扭亏为盈达 <strong class=\"text-white\">¥4.5 亿</strong>（去年同期亏损 ¥9 亿），Non-GAAP 经营利润更增至 ¥55 亿。\n                            随着服务收入稳健跑赢商品业务、供应链 AI 技术全链条落地及新业务亏损持续收窄，公司正加速从“规模扩张”转向“高质增长与股东回报”的复利新周期。\n                        </p>\n\n                        <!-- 核心投资结论高亮条 -->\n                        <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">利润与现金双重改善</div>\n                                <div class=\"text-white font-semibold\">Q2 经营利润同比大增 ¥54 亿扭亏为盈，达 ¥45 亿，现金流同步大幅转好</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">服务收入结构性升级</div>\n                                <div class=\"text-jdred-400 font-semibold\">第三方商家生态、广告及物流服务增速跑赢商品自营，平台生态持续繁荣</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">AI 赋能供应链全景落地</div>\n                                <div class=\"text-teal-400 font-semibold\">AI 智能骑手头盔、无人仓与商家智能大模型持续压降履约成本，提升运营效率</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 4个核心 KPI 卡片 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n                    <!-- KPI 1 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>2026 上半年总营收</span>\n                            <span class=\"p-1.5 rounded-lg bg-jdred-500/15 text-jdred-600 dark:text-jdred-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">¥662.1B</span>\n                            <span class=\"text-xs font-bold text-jdred-600 dark:text-jdred-400 bg-jdred-500/15 px-2 py-0.5 rounded\">+0.7% YoY</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            收入端保持小幅正增长，在大家电与手机等品类高基数及价格调整周期中展现极强韧性。\n                        </p>\n                    </div>\n\n                    <!-- KPI 2 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>Q2 2026 经营利润</span>\n                            <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">¥4.5B</span>\n                            <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">扭亏为盈</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            较去年同期亏损 ¥9 亿实现大幅扭亏，Non-GAAP 经营利润达 ¥55 亿，盈利拐点正式确立。\n                        </p>\n                    </div>\n\n                    <!-- KPI 3 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>京东零售经营利润率</span>\n                            <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~5.6%</span>\n                            <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">历史高位韧性</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            核心零售业务盈利能力保持极高韧性，百亿补贴投入与长期利润率实现良好平衡。\n                        </p>\n                    </div>\n\n                    <!-- KPI 4 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>Q3 2026 市场一致预期</span>\n                            <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$46.0B</span>\n                            <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">营收增速 +9.7%</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            华尔街共识预期 Q3 营收约 460.4 亿美元（约 3090 亿人民币），调整后 EPS 增长超 67%。\n                        </p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            一、 业务与收入架构 (Business & Revenue Architecture)\n            ========================================================= -->\n            <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-jdred-600 dark:text-jdred-400\">Section 01 · Business & Revenue Architecture</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：商品自营基本盘稳固，服务与供应链收入加速升级</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">2026 上半年总营收 ¥662.1B · 商品收入 ¥267.1B</span>\n                </div>\n\n                <!-- 交互式 Chart.js 双视图切换面板 -->\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n                    <!-- 左侧：双视图图表 -->\n                    <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n                            <div>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2023–2026 分部营收结构演进（商品收入 vs 服务与其他）</h3>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">服务收入占比持续扩大，平台生态与物流变现驱动高质量增长</p>\n                            </div>\n                            <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                                <button onclick=\"switchBizChart('revenue')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-jdred-600 dark:text-jdred-400 shadow-sm transition\">视图A：收入结构演进</button>\n                                <button onclick=\"switchBizChart('profit')\" id=\"btn-chart-pro\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：经营利润与扭亏趋势</button>\n                            </div>\n                        </div>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"bizArchitectureChart\"></canvas>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：结构性拆解核心洞察 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性拐点</h3>\n                            <ul class=\"space-y-4 text-sm\">\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-jdred-500/15 text-jdred-600 dark:text-jdred-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">商品收入基本盘（Online Direct Sales）</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            2026 上半年商品收入为 ¥2,671 亿元（同比小幅下滑 5.4%），主要受家电、3C 电子产品价格周期及去年高基数影响，但日常百货与超市品类起到了极强的客单防守与高频带货作用。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">服务与其他收入（Services & Others）</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                             Marketplace 平台佣金、广告服务及外部物流服务持续高速放量（单季度服务收入接近 800 亿元规模），成为拉动毛利率和整体盈利质量的强劲引擎。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">新业务减亏与 AI 供应链降本</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            即时零售与外卖等新业务在经历前期密集投入期后亏损持续收窄，AI 技术在智能仓储、无人配送及商家工具中的应用显著压降履约成本。\n                                        </p>\n                                    </div>\n                                </li>\n                            </ul>\n                        </div>\n                        <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n                            <span class=\"text-slate-500 dark:text-slate-400\">核心盈利催化剂</span>\n                            <span class=\"font-bold text-jdred-600 dark:text-jdred-400\">Q2 经营利润强势扭亏为盈（¥45 亿）</span>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 核心业务板块矩阵卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-jdred-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between mb-3\">\n                            <span class=\"px-2.5 py-1 rounded-md bg-jdred-500/15 text-jdred-600 dark:text-jdred-400 text-xs font-bold\">核心基本盘 · 京东零售</span>\n                            <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">经营利润率 ~5.6%</span>\n                        </div>\n                        <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">京东零售 (JD Retail)</h3>\n                        <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                            涵盖 3C 家电、大商超及日用百货自营与第三方商家。通过百亿补贴与供应链效率平衡，零售经营利润率保持在 5.6% 历史高位韧性区间。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between mb-3\">\n                            <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">供应链基石 · 京东物流</span>\n                            <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">一体化供应链服务</span>\n                        </div>\n                        <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">京东物流 (JDL)</h3>\n                        <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                            拥有全国首屈一指的仓配一体化物流网络。通过无人仓、智能调度及 AI 骑手头盔等科技创新持续优化履约成本，外部客户收入占比稳步提升。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between mb-3\">\n                            <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">新增长曲线 · 达达与创新</span>\n                            <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">亏损收窄、减负增效</span>\n                        </div>\n                        <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">新业务与即时零售</h3>\n                        <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                            包含达达、京东健康、京东产发及外卖等新业务。当前战略重心已从早期的激进规模扩张转变为精细化运营与减亏增效，成为利润释放的新变量。\n                        </p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            二、 行业地位与四重核心护城河 (Industry Position & Moat)\n            ========================================================= -->\n            <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：自营供应链、仓配物流与正品心智</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 中国自营供应链与正品心智标杆)</span>\n                </div>\n\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n                    <!-- 左侧：四重护城河深度解析 -->\n                    <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-jdred-500/15 text-jdred-600 dark:text-jdred-400 flex items-center justify-center font-bold text-sm\">01</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">行业罕见的自营供应链与正品心智</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                深度掌控商品采购、仓储、质检到配送的全链路自营模式，在 3C 家电及大商超领域树立起“多快好省、正品行货”的无可撼动消费者心智。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全国一体化仓配物流网络（京东物流）</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                运营数百个大型仓库与覆盖全国的末端配送网，实现核心城市“一日三送”与“次日达”，履约时效与送货上门服务满意度行业断层领先。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">开放生态与 Marketplace 繁荣</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                持续吸引第三方商家入驻，通过百亿补贴与流量扶持丰富商品长尾供给，带动服务收入高速增长并跑赢商品自营。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">AI 与供应链数智化深度融合</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                将大模型、商家智能视频编辑工具、无人仓储及智能骑手调度系统全面融入供应链毛细血管，持续压降运营成本并提升人效。\n                            </p>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：五维护城河雷达图 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">中国电商与供应链五维护城河量化雷达图</h3>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">京东 (JD) vs 传统综合电商平台 vs 垂直即时零售平台（满分 10 分）</p>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"moatRadarChart\"></canvas>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            三、 同行竞争格局横向对比 (Competitive Landscape)\n            ========================================================= -->\n            <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-jdred-600 dark:text-jdred-400\">Section 03 · Global Competitive Landscape</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：自营供应链专家 vs 货架电商与兴趣电商</h2>\n                    </div>\n                    <!-- 交互式筛选按钮 -->\n                    <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n                        <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-jdred-500 text-white shadow-sm transition\">全部阵营</button>\n                        <button onclick=\"filterCompetitors('ecommerce')\" data-filter=\"ecommerce\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">综合货架电商</button>\n                        <button onclick=\"filterCompetitors('social')\" data-filter=\"social\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">兴趣与内容电商</button>\n                    </div>\n                </div>\n\n                <!-- 横向对比矩阵表格 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n                    <div class=\"overflow-x-auto\">\n                        <table class=\"w-full text-left border-collapse\">\n                            <thead>\n                                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                                    <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心平台</th>\n                                    <th class=\"py-4 px-4 min-w-[130px]\">商业模式与核心定位</th>\n                                    <th class=\"py-4 px-4 min-w-[140px]\">履约与供应链壁垒</th>\n                                    <th class=\"py-4 px-4 min-w-[135px]\">盈利与利润率特征</th>\n                                    <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争评估</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                                <tr data-category=\"ecommerce\" class=\"bg-jdred-500/5 dark:bg-jdred-500/10 font-medium\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"flex items-center space-x-2\">\n                                            <span class=\"px-2 py-0.5 rounded bg-jdred-500 text-white text-[10px] font-extrabold\">行业绝对标杆</span>\n                                            <span class=\"font-bold text-slate-900 dark:text-white\">京东集团 JD.com (JD)</span>\n                                        </div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">自营供应链 + 一体化仓配物流</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">自营为主 + 开放第三方生态</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全国仓配一体，次日达/一日三送</td>\n                                    <td class=\"py-4 px-4 font-mono font-bold text-jdred-600 dark:text-jdred-400\">零售利润率 ~5.6% (稳健)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>供应链极致效率：</strong>在大件3C家电与商超领域正品心智无可替代，Q2 扭亏彰显强劲经营杠杆。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"ecommerce\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">阿里巴巴淘宝天猫 (BABA)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">中国全品类货架电商鼻祖</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">平台型 C2C/B2C 核心货架</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">菜鸟网络协同社会化物流</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">高变现率与强现金流</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>商家生态最深厚：</strong>长尾商品极其丰富，但重度依赖第三方商家，在特定大件自营时效上与京东各有侧重。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"social\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">抖音电商 / 快手电商</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">短视频与直播兴趣电商</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">内容种草与直播即兴购买</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">第三方快递承运为主</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">高成长、高营销投入</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>流量变现爆发力极强：</strong>通过内容激发非计划性消费，但在标品3C、大家电及高信任度大单品上仍不及京东。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"ecommerce\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">拼多多 PDD Holdings (PDD)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">极致性价比与全球化扩张</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">C2M 极致性价比与拼购</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">第三方快递轻资产模式</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">高毛利平台佣金与广告</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>下沉市场心智极强：</strong>以极低运营成本切入价格敏感用户，但在高端数码家电和送装一体服务上与京东形成差异化区隔。\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n                <!-- 配套 Chart.js 横向条形图：净利润率与盈利特征对比 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">中国主流电商平台盈利模式与经营利润率特征对比</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">京东零售经营利润率保持在 ~5.6% 稳健水平，Q2 盈利扭亏为盈凸显供应链效率释放</p>\n                        </div>\n                        <span class=\"text-xs font-semibold text-jdred-600 dark:text-jdred-400 bg-jdred-500/15 px-2.5 py-1 rounded\">自营供应链兼顾社会价值与长期盈利</span>\n                    </div>\n                    <div class=\"relative h-60 w-full\">\n                        <canvas id=\"compMarginChart\"></canvas>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n            ========================================================= -->\n            <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：利润现金双改善与估值安全边际</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q2 经营利润达 ¥4.5B · 净现金与现金流持续好转</span>\n                </div>\n\n                <!-- 1. 财务健康度四大硬核指标卡 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-jdred-600 dark:text-jdred-400 uppercase\">Gross Margin</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">约 10% 稳态</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            虽然自营商品毛利率相对偏低，但随着高毛利服务收入占比扩大，整体盈利结构持续优化。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Profit</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">¥4.5B (Q2)</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            Q2 经营利润由去年同期亏损 ¥9 亿转为盈利 ¥45 亿，Non-GAAP 经营利润更达 ¥55 亿。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Cash Flow Quality</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">利润与现金双改善</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            经营现金流显著好转，供应链周转效率提升保障了充沛的自由现金储备。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Shareholder Return</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">回购与分红并重</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            公司持续通过股份回购与稳定分红回报长期股东，估值性价比在大型中概股中名列前茅。\n                        </p>\n                    </div>\n                </div>\n\n                <!-- 2. 交互式 Chart.js 财务演进双轴图 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2023–2026 营收规模与季度经营利润扭亏演进趋势</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">收入保持平稳正增长，Q2 经营利润强势扭亏为盈标志着盈利修复拐点的顺利兑现</p>\n                        </div>\n                        <span class=\"text-xs font-mono font-bold text-jdred-600 dark:text-jdred-400 bg-jdred-500/10 px-2.5 py-1 rounded\">Q3 营收共识 ~$46.0B</span>\n                    </div>\n                    <div class=\"relative h-72 w-full\">\n                        <canvas id=\"valEvolutionChart\"></canvas>\n                    </div>\n                </div>\n\n                <!-- 3. 互动式复利推演计算器 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6\">\n                        <div>\n                            <h3 class=\"text-lg font-bold text-white\">京东 (JD) 投资回报与复利推演器</h3>\n                            <p class=\"text-xs text-slate-400 mt-1\">模拟在不同营收增速与盈利修复预期下的长期持仓市值与复合回报率</p>\n                        </div>\n                        <span class=\"text-xs px-3 py-1 rounded-full bg-slate-800 text-jdred-300 border border-slate-700\">交互式推演模型</span>\n                    </div>\n\n                    <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-8 items-center\">\n                        <div class=\"space-y-5\">\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">初始投资本金 (USD)</span>\n                                    <span id=\"invVal\" class=\"font-bold text-white\">$20,000</span>\n                                </div>\n                                <input id=\"invSlider\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"20000\" class=\"w-full accent-jdred-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">持有年限 (Years)</span>\n                                    <span id=\"yrVal\" class=\"font-bold text-white\">3 年</span>\n                                </div>\n                                <input id=\"yrSlider\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"3\" class=\"w-full accent-jdred-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">预期年化营收/盈利增速</span>\n                                    <span id=\"grVal\" class=\"font-bold text-jdred-400\">10.0%</span>\n                                </div>\n                                <input id=\"grSlider\" type=\"range\" min=\"2\" max=\"25\" step=\"1\" value=\"10\" class=\"w-full accent-jdred-400 cursor-pointer\">\n                            </div>\n                        </div>\n\n                        <div class=\"lg:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4\">\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末预计总资产市值</div>\n                                <div id=\"finalBalance\" class=\"text-2xl font-bold text-white mt-2\">$26,620</div>\n                                <div id=\"totalGainPct\" class=\"text-xs text-jdred-400 mt-1\">累计总回报 +33.1%</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末对应隐含股价</div>\n                                <div id=\"impliedPrice\" class=\"text-2xl font-bold text-teal-400 mt-2\">$36.50</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">基于盈利修复与估值重估</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">隐含复合年化回报 (CAGR)</div>\n                                <div id=\"cagrVal\" class=\"text-2xl font-bold text-amber-400 mt-2\">10.0%</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">主营稳健增长与利润改善</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            五、 投资决策与风险配置框架 (Investment Decision & Risk)\n            ========================================================= -->\n            <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-jdred-600 dark:text-jdred-400\">Section 05 · Investment Decision & Risk Allocation</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与核心风险</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：中概股资产配置中的高性价比价值标的</span>\n                </div>\n\n                <!-- 1. 三情景估值推演卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-jdred-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-jdred-500/15 text-jdred-600 dark:text-jdred-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-jdred-600 dark:text-jdred-400\">概率：30%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">盈利目标：零售利润率突破 6%</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>宏观消费超预期回暖，家电以旧换新与数码换机潮爆发，第三方服务收入爆发，新业务全面实现盈亏平衡，估值戴维斯双击。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-jdred-600 dark:text-jdred-400\">\n                            潜在上行空间：+40% 至 +60%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">盈利目标：零售利润率稳守 5.5%</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>营收保持 5% 左右稳健增长，Q3/Q4 盈利持续兑现市场共识预期，供应链 AI 降本增效稳步推进，现金流保持充沛。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n                            潜在上行空间：+20% 至 +30%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防御目标：维持基本盈利</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>国内可选消费复苏斜率放缓，行业价格竞争再次加剧侵蚀自营毛利，新业务减亏进程阶段性反复。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n                            潜在下行回撤：-12% 至 -20%\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 2. 四大核心风险评估矩阵 -->\n                <div>\n                    <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n                    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 国内可选消费复苏波动风险</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">3C 家电等大件消费弹性</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                京东核心基本盘深度绑定手机、电脑、大家电等耐用消费品，若居民大宗消费意愿恢复缓慢，将直接对商品自营收入形成压制。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 行业价格竞争再次加剧风险</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">电商平台促销战与补贴消耗</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                国内电商存量博弈格局下，各平台若再度掀起高强度价格补贴战，可能对京东零售维持 5.6% 经营利润率的目标构成阶段性考验。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 新业务投入与减亏不及预期</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">即时零售与外卖扩张消耗</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                尽管 Q2 整体实现扭亏，但外卖及即时零售新业务若未能按计划持续收窄亏损，可能重新拖累集团整体利润释放斜率。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 供应链重资产资本开支压力</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：低中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">物流仓储基础设施投入</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                作为重资产供应链模式代表，大规模仓配物流基础设施的持续迭代需要稳定的资本开支支持，对现金流管理提出较高要求。\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n            ========================================================= -->\n            <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n                    </div>\n                    <div class=\"flex items-center space-x-2 no-print\">\n                        <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-jdred-500/15 text-jdred-600 dark:text-jdred-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n                        <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n                    </div>\n                </div>\n\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n                        点击勾选机构财报追踪已验证达标的核心指标（状态自动本地保存），用高频基本面事实动态校准投资逻辑：\n                    </p>\n\n                    <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n                        <!-- KPI 1 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E1251B] focus:ring-jdred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. Q3 财报营收与利润是否达华尔街一致预期（营收 ~$46B）</span>\n                                    <span class=\"text-[11px] font-mono text-jdred-600 dark:text-jdred-400 font-semibold shrink-0\">财报共识验证</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪 2026 年 11 月 17 日披露的 Q3 财报，验证营收增速（约 +9.7%）及调整后 EPS（预期 $0.88）是否顺利超越预期。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 2 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E1251B] focus:ring-jdred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 京东零售经营利润率能否稳守 5%–5.6% 历史高位</span>\n                                    <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">零售基本盘盈利</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    监控核心零售板块在百亿补贴背景下的利润率表现，确认低价策略未侵蚀长期核心盈利能力。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 3 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E1251B] focus:ring-jdred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 服务与其他收入增速是否持续跑赢商品自营业务</span>\n                                    <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">收入结构升级</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    观察第三方商家生态（Marketplace）佣金、广告变现及外部物流服务收入占总营收比例的扩张斜率。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 4 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E1251B] focus:ring-jdred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 新业务（即时零售、外卖等）亏损是否持续显著收窄</span>\n                                    <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">新业务减亏进展</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪新业务板块经营利润亏损额，验证管理层从“跑马圈地”向“精细化运营”转型的财务成效。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 5 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E1251B] focus:ring-jdred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. AI 技术在供应链与履约环节的实际降本增效成果</span>\n                                    <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">AI 科技红利兑现</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    评估无人仓储、智能配送调度及商家 AI 智能工具对京东物流单件履约成本（FUL/Order）的压降效果。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 6 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E1251B] focus:ring-jdred-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 股东回报力度（股票回购金额与分红增长率）</span>\n                                    <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">股东价值回报</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    监控公司每季度现金流回馈股东的力度，重点关注股份回购总额及对每股收益（EPS）的增厚倍数。\n                                </p>\n                            </div>\n                        </label>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            页脚免责声明 (Disclaimer Footer)\n            ========================================================= -->\n            <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n                <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n                    <span>京东集团 JD.com (NASDAQ: JD / HKEX: 9618) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n                    <span>数据基准：2026 财年半年报及 Q3 前瞻一致预期</span>\n                </div>\n                <p class=\"leading-relaxed\">\n                    <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、财报电话会议纪要及市场公开一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的财务预测、三情景估值模型及推演数据均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n                </p>\n            </footer>\n\n        </div>\n    </main>\n\n    <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n    <script>\n    function toggleTheme() {\n        const html = document.documentElement;\n        html.classList.toggle('dark');\n        updateChartsTheme();\n    }\n\n    function toggleMobileMenu() {\n        const drawer = document.getElementById('mobile-drawer');\n        drawer.classList.toggle('hidden');\n    }\n\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n        const scrollTop = window.scrollY;\n        const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n        const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n        document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n        let currentId = 'sec-exec';\n        sections.forEach(sec => {\n            const top = sec.offsetTop - 160;\n            if (scrollTop >= top) {\n                currentId = sec.getAttribute('id');\n            }\n        });\n\n        navLinks.forEach(link => {\n            link.classList.remove('active');\n            const numSpan = link.querySelector('span span');\n            if (numSpan) {\n                numSpan.classList.remove('text-jdred-400');\n                numSpan.classList.add('text-slate-500');\n            }\n            if (link.dataset.target === currentId) {\n                link.classList.add('active');\n                if (numSpan) {\n                    numSpan.classList.remove('text-slate-500');\n                    numSpan.classList.add('text-jdred-400');\n                }\n            }\n        });\n    });\n\n    function filterCompetitors(category) {\n        document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n            if (btn.dataset.filter === category) {\n                btn.classList.add('bg-jdred-500', 'text-white', 'font-semibold', 'shadow-sm');\n                btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            } else {\n                btn.classList.remove('bg-jdred-500', 'text-white', 'font-semibold', 'shadow-sm');\n                btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            }\n        });\n\n        const rows = document.querySelectorAll('#comp-table-body tr');\n        rows.forEach(row => {\n            const rowCat = row.dataset.category;\n            if (category === 'all' || rowCat === category) {\n                row.style.display = '';\n            } else {\n                row.style.display = 'none';\n            }\n        });\n    }\n\n    const KPI_STORAGE_KEY = 'jd_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n        try {\n            const saved = localStorage.getItem(KPI_STORAGE_KEY);\n            if (saved) {\n                const stateMap = JSON.parse(saved);\n                document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n                    if (typeof stateMap[cb.id] === 'boolean') {\n                        cb.checked = stateMap[cb.id];\n                    }\n                });\n            }\n        } catch (e) {}\n        updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n        const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n        const total = checkboxes.length;\n        let checkedCount = 0;\n        const stateMap = {};\n\n        checkboxes.forEach(cb => {\n            stateMap[cb.id] = cb.checked;\n            if (cb.checked) checkedCount++;\n        });\n\n        const pct = Math.round((checkedCount / total) * 100);\n        document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n        try {\n            localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n        } catch (e) {}\n    }\n\n    function resetKpiChecklist() {\n        document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            cb.checked = false;\n        });\n        updateKpiChecklist();\n    }\n\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compMarginChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'revenue';\n\n    function getChartColors() {\n        const isDark = document.documentElement.classList.contains('dark');\n        return {\n            text: isDark ? '#CBD5E1' : '#475569',\n            grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n            radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n        };\n    }\n\n    function initBizChart() {\n        const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n        const colors = getChartColors();\n\n        const revConfig = {\n            type: 'bar',\n            data: {\n                labels: ['2023', '2024', '2025', '2026 上半年', '2026 全年(E)'],\n                datasets: [\n                    {\n                        label: '商品自营收入 (Online Direct Sales) (¥B)',\n                        data: [870.0, 910.0, 950.0, 534.2, 1080.0],\n                        backgroundColor: '#E1251B',\n                        borderRadius: 4,\n                    },\n                    {\n                        label: '服务与其他收入 (Services & Others) (¥B)',\n                        data: [210.0, 240.0, 280.0, 127.9, 290.0],\n                        backgroundColor: '#3B82F6',\n                        borderRadius: 4,\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `${ctx.dataset.label}: ¥${ctx.parsed.y}B`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        stacked: true,\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        stacked: true,\n                        max: 1450,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '¥' + v + 'B' }\n                    }\n                }\n            }\n        };\n\n        const proConfig = {\n            type: 'bar',\n            data: {\n                labels: ['2023 全年', '2024 全年', '2025 全年', '2026 Q1', '2026 Q2'],\n                datasets: [\n                    {\n                        label: '季度/年度经营利润 Operating Income (¥B)',\n                        data: [26.0, 31.0, 27.5, 3.2, 4.5],\n                        backgroundColor: '#10B981',\n                        borderRadius: 6,\n                        barThickness: 28\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: { display: false },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `经营利润: ¥${ctx.parsed.y}B (Q2 扭亏为盈)`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        min: -2,\n                        max: 35,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '¥' + v + 'B' }\n                    }\n                }\n            }\n        };\n\n        if (bizChartInstance) bizChartInstance.destroy();\n        bizChartInstance = new Chart(ctx, currentBizMode === 'revenue' ? revConfig : proConfig);\n    }\n\n    function switchBizChart(mode) {\n        currentBizMode = mode;\n        const btnRev = document.getElementById('btn-chart-rev');\n        const btnPro = document.getElementById('btn-chart-pro');\n        const titleEl = document.getElementById('biz-chart-title');\n        const subEl = document.getElementById('biz-chart-sub');\n\n        if (mode === 'revenue') {\n            btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-jdred-600 dark:text-jdred-400 shadow-sm transition';\n            btnPro.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = '2023–2026 分部营收结构演进（商品收入 vs 服务与其他）';\n            subEl.textContent = '服务收入占比持续扩大，平台生态与物流变现驱动高质量增长';\n        } else {\n            btnPro.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-jdred-600 dark:text-jdred-400 shadow-sm transition';\n            btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = '经营利润演进趋势（Q2 2026 强势扭亏为盈 ¥4.5 亿）';\n            subEl.textContent = '新业务减亏与零售利润率稳健驱动整体盈利拐点顺利兑现';\n        }\n        initBizChart();\n    }\n\n    function initRadarChart() {\n        const ctx = document.getElementById('moatRadarChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (radarChartInstance) radarChartInstance.destroy();\n        radarChartInstance = new Chart(ctx, {\n            type: 'radar',\n            data: {\n                labels: [\n                    '自营正品心智与供应链信任',\n                    '全国仓配一体物流履约时效',\n                    '3C家电大件品类绝对定价权',\n                    '第三方商家生态与广告变现',\n                    'AI与供应链数智化降本增效'\n                ],\n                datasets: [\n                    {\n                        label: '京东集团 (JD)',\n                        data: [9.8, 9.7, 9.6, 8.5, 9.2],\n                        borderColor: '#E1251B',\n                        backgroundColor: 'rgba(225, 37, 27, 0.22)',\n                        pointBackgroundColor: '#E1251B',\n                        borderWidth: 2.5\n                    },\n                    {\n                        label: '传统平台型电商 (阿里/拼多多)',\n                        data: [8.2, 7.8, 7.5, 9.5, 8.0],\n                        borderColor: '#3B82F6',\n                        backgroundColor: 'rgba(59, 130, 246, 0.14)',\n                        pointBackgroundColor: '#3B82F6',\n                        borderWidth: 1.8\n                    },\n                    {\n                        label: '内容/兴趣电商 (抖音/快手)',\n                        data: [7.0, 6.0, 5.5, 9.0, 6.5],\n                        borderColor: '#94A3B8',\n                        backgroundColor: 'rgba(148, 163, 184, 0.12)',\n                        pointBackgroundColor: '#94A3B8',\n                        borderWidth: 1.5,\n                        borderDash: [4, 4]\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n                    }\n                },\n                scales: {\n                    r: {\n                        min: 0,\n                        max: 10,\n                        ticks: { display: false, stepSize: 2 },\n                        grid: { color: colors.grid },\n                        angleLines: { color: colors.radarAngle },\n                        pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initCompMarginChart() {\n        const ctx = document.getElementById('compMarginChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (compMarginChartInstance) compMarginChartInstance.destroy();\n        compMarginChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: [\n                    '京东零售 (JD Retail · 经营利润率)',\n                    '阿里巴巴 (淘宝天猫集团)',\n                    '拼多多 (PDD Holdings)',\n                    '抖音/快手电商 (内容生态)'\n                ],\n                datasets: [{\n                    label: '核心零售/电商经营利润率 (%)',\n                    data: [5.6, 20.0, 25.0, 15.0],\n                    backgroundColor: [\n                        '#E1251B',\n                        '#3B82F6',\n                        '#10B981',\n                        '#F59E0B'\n                    ],\n                    borderRadius: 6,\n                    barThickness: 24\n                }]\n            },\n            options: {\n                indexAxis: 'y',\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: { display: false },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `利润率特征: ${ctx.parsed.x}%`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        max: 30,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n                    },\n                    y: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initValEvolutionChart() {\n        const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n        valEvolutionChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: ['2023', '2024', '2025', '2026 上半年', '2026 全年(E)'],\n                datasets: [\n                    {\n                        type: 'bar',\n                        label: '全年总营收 (¥B)',\n                        data: [1082, 1150, 1230, 662.1, 1370],\n                        backgroundColor: 'rgba(225, 37, 27, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 24,\n                        yAxisID: 'y'\n                    },\n                    {\n                        type: 'bar',\n                        label: '全年经营利润 (¥B)',\n                        data: [26.0, 31.0, 27.5, 12.2, 29.0],\n                        backgroundColor: 'rgba(59, 130, 246, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 24,\n                        yAxisID: 'y1'\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => ctx.dataset.yAxisID === 'y'\n                                ? `${ctx.dataset.label}: ¥${ctx.parsed.y}B`\n                                : `${ctx.dataset.label}: ¥${ctx.parsed.y}B`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        type: 'linear',\n                        position: 'left',\n                        max: 1600,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '¥' + v + 'B' }\n                    },\n                    y1: {\n                        type: 'linear',\n                        position: 'right',\n                        min: 0,\n                        max: 40,\n                        grid: { drawOnChartArea: false },\n                        ticks: { color: '#3B82F6', font: { size: 11, weight: '600' }, callback: v => '¥' + v + 'B' }\n                    }\n                }\n            }\n        });\n    }\n\n    function updateChartsTheme() {\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n    }\n\n    // Calculator Logic\n    const invSlider = document.getElementById('invSlider');\n    const yrSlider = document.getElementById('yrSlider');\n    const grSlider = document.getElementById('grSlider');\n\n    function updateCalculator() {\n        const principal = parseFloat(invSlider.value);\n        const years = parseInt(yrSlider.value);\n        const growthRate = parseFloat(grSlider.value) / 100;\n\n        document.getElementById('invVal').textContent = '$' + principal.toLocaleString();\n        document.getElementById('yrVal').textContent = years + ' 年';\n        document.getElementById('grVal').textContent = (growthRate * 100).toFixed(1) + '%';\n\n        const finalVal = principal * Math.pow(1 + growthRate, years);\n        const totalGain = finalVal - principal;\n        const gainPct = (totalGain / principal) * 100;\n        const impliedPrice = 28 * Math.pow(1 + growthRate * 0.85, years);\n\n        document.getElementById('finalBalance').textContent = '$' + Math.round(finalVal).toLocaleString();\n        document.getElementById('totalGainPct').textContent = '累计总回报 +' + gainPct.toFixed(1) + '%';\n        document.getElementById('impliedPrice').textContent = '$' + impliedPrice.toFixed(2);\n        document.getElementById('cagrVal').textContent = (growthRate * 100).toFixed(1) + '%';\n    }\n\n    [invSlider, yrSlider, grSlider].forEach(el => el.addEventListener('input', updateCalculator));\n\n    window.addEventListener('DOMContentLoaded', () => {\n        loadKpiChecklist();\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n        updateCalculator();\n    });\n    </script>\n</body>\n</html>\n"};
